// Package store owns the SQLite database: opening it with the right pragmas, running the embedded migrations (after a
// VACUUM INTO backup), and transactions. Queries are generated by sqlc into internal/store/db.
//
// There are two connection pools. The writer has exactly one connection and starts every transaction with BEGIN
// IMMEDIATE, so writes queue on busy_timeout instead of failing with SQLITE_BUSY when a read upgrades to a write. The
// reader pool is query_only, so a write sent to it by mistake fails instead of bypassing the writer.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"net/url"
	"os"
	"path/filepath"

	_ "modernc.org/sqlite" // registers the "sqlite" driver

	"github.com/Kate-0713/pihole-rbac/internal/store/db"
	"github.com/Kate-0713/pihole-rbac/migrations"
)

// FileName is the database file inside the data directory.
const FileName = "pihole-rbac.db"

const (
	busyTimeoutMS      = 5000
	defaultReadConns   = 4
	defaultKeepBackups = 5
)

// Options configures Open. Only DataDir is required.
type Options struct {
	DataDir     string
	Logger      *slog.Logger // nil means slog.Default()
	ReadConns   int          // reader pool size, default 4
	KeepBackups int          // pre-migration backups to keep, default 5
}

// Store is the open database. It is safe for concurrent use.
type Store struct {
	dataDir     string
	path        string
	log         *slog.Logger
	keepBackups int
	w           *sql.DB // single connection, all writes
	r           *sql.DB // query_only pool
}

// Open opens (creating if needed) the database in opts.DataDir and applies any pending migrations.
func Open(ctx context.Context, opts Options) (*Store, error) {
	return open(ctx, opts, migrations.FS)
}

// open takes the migrations as a parameter so tests can add or remove migrations.
func open(ctx context.Context, opts Options, migrationsFS fs.FS) (_ *Store, err error) {
	if opts.DataDir == "" {
		return nil, errors.New("store: data directory not set")
	}
	if opts.Logger == nil {
		opts.Logger = slog.Default()
	}
	if opts.ReadConns <= 0 {
		opts.ReadConns = defaultReadConns
	}
	if opts.KeepBackups <= 0 {
		opts.KeepBackups = defaultKeepBackups
	}
	if err := os.MkdirAll(opts.DataDir, 0o750); err != nil {
		return nil, fmt.Errorf("store: create data directory: %w", err)
	}

	path := filepath.Join(opts.DataDir, FileName)
	// Create the file ourselves so it's 0600 on Linux. SQLite gives the -wal and -shm files the same mode.
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, fmt.Errorf("store: create database file: %w", err)
	}
	f.Close()

	s := &Store{dataDir: opts.DataDir, path: path, log: opts.Logger, keepBackups: opts.KeepBackups}
	defer func() {
		if err != nil {
			s.Close()
		}
	}()

	if s.w, err = sql.Open("sqlite", dsn(path, false)); err != nil {
		return nil, fmt.Errorf("store: open writer: %w", err)
	}
	s.w.SetMaxOpenConns(1)
	s.w.SetMaxIdleConns(1)
	s.w.SetConnMaxLifetime(0)
	s.w.SetConnMaxIdleTime(0)
	if err := checkPragmas(ctx, s.w, false); err != nil {
		return nil, err
	}

	if err := s.migrate(ctx, migrationsFS); err != nil {
		return nil, err
	}

	if s.r, err = sql.Open("sqlite", dsn(path, true)); err != nil {
		return nil, fmt.Errorf("store: open reader: %w", err)
	}
	s.r.SetMaxOpenConns(opts.ReadConns)
	s.r.SetMaxIdleConns(opts.ReadConns)
	if err := checkPragmas(ctx, s.r, true); err != nil {
		return nil, err
	}
	return s, nil
}

// dsn builds a modernc.org/sqlite DSN. The path has no "file:" prefix, so the driver strips the query string itself
// and Windows paths need no URI escaping. _pragma values run on every new connection, in order.
func dsn(path string, readOnly bool) string {
	q := url.Values{}
	q.Add("_pragma", "busy_timeout("+fmt.Sprint(busyTimeoutMS)+")")
	q.Add("_pragma", "foreign_keys(1)")
	if readOnly {
		q.Add("_pragma", "query_only(1)")
	} else {
		q.Add("_pragma", "journal_mode(WAL)")
		q.Set("_txlock", "immediate")
	}
	return path + "?" + q.Encode()
}

// checkPragmas fails if the DSN settings didn't take effect, which would otherwise go unnoticed (a typo in a _pragma
// is silently ignored by SQLite).
func checkPragmas(ctx context.Context, d *sql.DB, readOnly bool) error {
	var journal string
	var fk, busy, queryOnly int
	conn, err := d.Conn(ctx)
	if err != nil {
		return fmt.Errorf("store: connect: %w", err)
	}
	defer conn.Close()
	for _, p := range []struct {
		name string
		dst  any
	}{
		{"journal_mode", &journal},
		{"foreign_keys", &fk},
		{"busy_timeout", &busy},
		{"query_only", &queryOnly},
	} {
		if err := conn.QueryRowContext(ctx, "PRAGMA "+p.name).Scan(p.dst); err != nil {
			return fmt.Errorf("store: read pragma %s: %w", p.name, err)
		}
	}
	switch {
	case journal != "wal":
		return fmt.Errorf("store: journal_mode is %q, want wal", journal)
	case fk != 1:
		return errors.New("store: foreign_keys is off")
	case busy != busyTimeoutMS:
		return fmt.Errorf("store: busy_timeout is %d, want %d", busy, busyTimeoutMS)
	case readOnly != (queryOnly == 1):
		return fmt.Errorf("store: query_only is %d on the %s pool", queryOnly, map[bool]string{true: "reader", false: "writer"}[readOnly])
	}
	return nil
}

// Close closes both pools.
func (s *Store) Close() error {
	var errs []error
	if s.r != nil {
		errs = append(errs, s.r.Close())
	}
	if s.w != nil {
		errs = append(errs, s.w.Close())
	}
	return errors.Join(errs...)
}

// Read returns queries bound to the read-only pool. Any write through it fails.
func (s *Store) Read() *db.Queries {
	return db.New(s.r)
}

// WithTx runs fn in a write transaction (BEGIN IMMEDIATE) and commits if fn returns nil. Any error, or a panic, rolls
// back. Every write goes through here, so a change, its invariant checks and its audit row commit or fail together.
func (s *Store) WithTx(ctx context.Context, fn func(q *db.Queries) error) error {
	tx, err := s.w.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("store: begin: %w", err)
	}
	defer tx.Rollback() // no-op after Commit

	if err := fn(db.New(tx)); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: commit: %w", err)
	}
	return nil
}
